-- LOCAL PostgreSQL fixture only; never run on the live project.
\set ON_ERROR_STOP on
INSERT INTO public.teams(id,company_id,name) VALUES
('50000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Design'),
('50000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Other');
UPDATE public.employees SET team_id='50000000-0000-4000-8000-000000000001'
WHERE id='40000000-0000-4000-8000-000000000001';
SELECT tests.raises($q$UPDATE public.employees SET team_id='50000000-0000-4000-8000-000000000002' WHERE id='40000000-0000-4000-8000-000000000001'$q$,'foreign key constraint');
SELECT tests.ok((SELECT count(*)=52 FROM public.avatar_items),'actual FE catalogue');
BEGIN;
SET LOCAL ROLE anon;
SELECT tests.raises('SELECT * FROM public.avatar_items','permission denied');
SELECT tests.raises($q$SELECT public.save_character(NULL,'{}')$q$,'permission denied');
ROLLBACK;
BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
SELECT tests.ok((SELECT count(*)=1 FROM public.teams),'team isolation');
SELECT tests.ok((SELECT count(*)=3 FROM public.employee_avatars),'avatar company isolation');
SELECT tests.ok((public.get_my_membership()->'avatar'->>'is_complete')='false','existing member avatar backfill');
SELECT tests.ok(public.get_employee_work_info(NULL) IS NULL,'null target');
SELECT tests.ok(public.get_employee_work_info('40000000-0000-4000-8000-000000000003') IS NULL,'cross company work info');
SELECT tests.ok((public.get_employee_work_info('40000000-0000-4000-8000-000000000001')->'team'->>'name')='Design','work info team');
SELECT tests.ok((public.get_employee_work_info('40000000-0000-4000-8000-000000000001')->'seat'->>'label')='A1','work info location');
SELECT tests.ok((public.get_employee_work_info('40000000-0000-4000-8000-000000000001')->'profile'->>'visual_sensitivity')='4','work info sensitivities');
SELECT public.set_employee_status('40000000-0000-4000-8000-000000000001','working');
SELECT public.set_status_message('40000000-0000-4000-8000-000000000001',repeat('가',20));
SELECT tests.raises($q$SELECT public.set_status_message('40000000-0000-4000-8000-000000000001',repeat('가',21))$q$,'INVALID_STATUS_MESSAGE');
SELECT public.set_quick_emoji('40000000-0000-4000-8000-000000000001','coffee');
SELECT tests.ok((SELECT status='working' AND away_reason IS NULL AND status_message=repeat('가',20) AND quick_emoji_id='coffee'
 FROM public.employee_statuses WHERE employee_id='40000000-0000-4000-8000-000000000001'),'emoji independent from message/attendance');
SELECT public.set_status_message('40000000-0000-4000-8000-000000000001','separate');
SELECT tests.ok((SELECT quick_emoji_id='coffee' FROM public.employee_statuses WHERE employee_id='40000000-0000-4000-8000-000000000001'),'message retains emoji');
SELECT tests.ok((SELECT c->'status'->'quick_emoji'->>'emoji'='☕' FROM public.get_sensory_cards('10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001') c),'emoji card output');
SELECT tests.raises($q$SELECT public.set_quick_emoji('40000000-0000-4000-8000-000000000002','coffee')$q$,'NOT_YOUR_EMPLOYEE');
SELECT tests.raises($q$SELECT public.set_quick_emoji('40000000-0000-4000-8000-000000000001','unknown')$q$,'INVALID_QUICK_EMOJI');
SELECT tests.raises('UPDATE public.employee_statuses SET quick_emoji_id=NULL','permission denied');
SELECT tests.raises('UPDATE public.employees SET team_id=NULL','permission denied');
SELECT tests.raises('UPDATE public.employee_avatars SET selections=''{}''','permission denied');
SELECT tests.raises($q$SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000002','{}',false)$q$,'NOT_YOUR_EMPLOYEE');
SELECT tests.raises($q$SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000001','{"unknown":"x"}',false)$q$,'INVALID_AVATAR_CATEGORY');
SELECT tests.raises($q$SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000001','{"hair_style":"unknown"}',false)$q$,'INVALID_AVATAR_ITEM');
SELECT tests.raises($q$SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000001','{}')$q$,'INCOMPLETE_AVATAR');
SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000001','{"hair_style":"bob"}',false);
SELECT public.save_character('40000000-0000-4000-8000-000000000001','{"hair":5,"hairColor":7,"eye":5,"gender":"m","outfit":5,"color":19,"skin":null}');
SELECT tests.ok((public.get_my_membership()->'avatar'->'character')='{"hair":5,"hairColor":7,"eye":5,"gender":"m","outfit":5,"color":19,"skin":null}'::jsonb,'native FE character roundtrip');
SELECT tests.ok((SELECT c->'avatar'->'character'->>'hair'='5' FROM public.get_sensory_cards('10000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001') c),'native FE character in card');
SELECT tests.raises($q$SELECT public.save_character('40000000-0000-4000-8000-000000000001','{"hair":6,"hairColor":0,"eye":0,"gender":"f","outfit":0,"color":0,"skin":null}')$q$,'INVALID_CHARACTER');
SELECT tests.raises($q$SELECT public.save_character('40000000-0000-4000-8000-000000000001','{"hair":"0","hairColor":0,"eye":0,"gender":"f","outfit":0,"color":0,"skin":null}')$q$,'INVALID_CHARACTER');
SELECT tests.raises($q$SELECT public.save_character('40000000-0000-4000-8000-000000000001','{"hair":0,"hairColor":0,"eye":0,"gender":"x","outfit":0,"color":0,"skin":null}')$q$,'INVALID_CHARACTER');
SELECT tests.raises($q$SELECT public.save_character('40000000-0000-4000-8000-000000000001','{"hair":0,"hairColor":0,"eye":0,"gender":"f","outfit":0,"color":0,"skin":"blue"}')$q$,'INVALID_AVATAR_ITEM');
SELECT public.save_employee_avatar('40000000-0000-4000-8000-000000000001','{"special_skin":"purple"}');
SELECT public.set_employee_status('40000000-0000-4000-8000-000000000001','off_work');
SELECT tests.ok((SELECT status_message='' AND quick_emoji_id='coffee' FROM public.employee_statuses WHERE employee_id='40000000-0000-4000-8000-000000000001'),'checkout clears message; independent emoji retained');
SELECT tests.ok((public.get_my_membership()->'avatar'->>'is_complete')='true','checkout retains avatar');
SELECT public.set_quick_emoji('40000000-0000-4000-8000-000000000001',NULL);
SELECT tests.ok((SELECT quick_emoji_id IS NULL FROM public.employee_statuses WHERE employee_id='40000000-0000-4000-8000-000000000001'),'clear emoji');
SELECT tests.raises($q$SELECT public.set_status_message('40000000-0000-4000-8000-000000000001','x')$q$,'EMPLOYEE_NOT_WORKING');
SELECT public.choose_seat('40000000-0000-4000-8000-000000000001',NULL);
SELECT tests.ok((SELECT count(*)=1 FROM public.notifications),'own seat notification');
SELECT public.mark_notification_read(id) FROM public.notifications;
SELECT tests.ok((SELECT bool_and(read_at IS NOT NULL) FROM public.notifications),'acknowledge notification');
SELECT public.mark_notification_read(id) FROM public.notifications;
SELECT tests.raises('INSERT INTO public.notifications(employee_id,kind,title) VALUES(NULL,''system'',''x'')','permission denied');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
SELECT tests.ok((SELECT count(*)=0 FROM public.notifications),'colleague notification hidden');
SELECT tests.ok((SELECT is_complete FROM public.employee_avatars WHERE employee_id='40000000-0000-4000-8000-000000000001'),'colleague avatar visible');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
SELECT tests.ok((SELECT count(*)=1 FROM public.employee_avatars),'other company avatar isolation');
COMMIT;
SELECT tests.raises($q$UPDATE public.employee_statuses SET status='working',status_message=repeat('x',21) WHERE employee_id='40000000-0000-4000-8000-000000000001'$q$,'check constraint');
UPDATE public.avatar_items SET enabled=false WHERE category_id='special_skin';
